  system = "vertikal",
  kulturId = "acker",
  regionId = "de-sued",
  dbProHa,
  vermarktung = "eeg",
  anteil = AGRI.beteiligungAnteil.standard,
  laufzeit = FREIFLAECHE.laufzeit,
} = {}) {
  const kultur = kulturById(kulturId);
