// „Dienstbarkeit, Rangrücktritt und Eintrittsrecht der Bank“ in pachtvertrag-solarpark.js.

import { PACHT, FREIFLAECHE, STAND } from "@/lib/invest/markt";
import { fmt, fmtEur } from "@/lib/rechner/annahmen";

