// KNE „Artenreiches Grünland im Solarpark etablieren“ 07/2025, GAPDZV § 12, Fraunhofer ISE
// Agri-PV-Leitfaden 4. Aufl. 06/2025, DIN SPEC 91434/91492).

import { AGRI, PACHT, FREIFLAECHE, STAND } from "@/lib/invest/markt";
