    pachtJahr0,
    wege: [pachten, eigenInv, beteiligung],
    laufzeit,
  };
}

/** Jahr, in dem der kumulierte Cashflow erstmals ≥ 0 ist (linear interpoliert) */
export function amortisation(cf) {
  let kum = cf[0];
  for (let t = 1; t < cf.length; t++) {
    const vorher = kum;
    kum += cf[t];
    if (kum >= 0 && vorher < 0) return t - 1 + -vorher / cf[t];
  }
  return null;
}

