const PILOTEN = [
  { ort: "Gelsdorf (RP), 2021", kultur: "Bio-Äpfel, acht Sorten", kwp: 258, m2: 3552, besonders: "semitransparente Doppelglasmodule, teils nachgeführt; Vergleich mit Hagelnetz und Folie" },
